namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>A real local HTTP server standing in for the provider's REST API.</summary>
internal sealed class FakeProvider : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly Task loop;

    public FakeProvider(int status, string body)
    {
        var port = GetFreePort();
        BaseAddress = new Uri($"http://localhost:{port}");
        listener.Prefixes.Add($"http://localhost:{port}/");
        listener.Start();
        loop = Task.Run(async () =>
        {
            var context = await listener.GetContextAsync();
            using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            ReceivedBody = await reader.ReadToEndAsync();
            ReceivedMethod = context.Request.HttpMethod;
            ReceivedPath = context.Request.Url!.AbsolutePath;
            ReceivedContentType = context.Request.ContentType;
            context.Response.StatusCode = status;
            context.Response.ContentType = "application/json";
            var bytes = Encoding.UTF8.GetBytes(body);
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        });
    }

    public Uri BaseAddress { get; }
    public string? ReceivedBody { get; private set; }
    public string? ReceivedMethod { get; private set; }
    public string? ReceivedPath { get; private set; }
    public string? ReceivedContentType { get; private set; }

    public Task Completed => loop;

    public void Dispose() => listener.Close();

    private static int GetFreePort()
    {
        var tcp = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        tcp.Start();
        var port = ((IPEndPoint)tcp.LocalEndpoint).Port;
        tcp.Stop();
        return port;
    }
}
