using System.Text.Json;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, FakeProvider Provider)> Call(int status, string body)
    {
        using var provider = new FakeProvider(status, body);
        using var client = new HttpClient { BaseAddress = provider.BaseAddress };
        var outcome = await new HttpPaymentGateway(client)
            .AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);
        await provider.Completed;
        return (outcome, provider);
    }

    [Fact]
    public async Task The_request_is_a_json_post_to_the_authorizations_endpoint()
    {
        var (_, provider) = await Call(200, """{"status":"approved"}""");

        Assert.Equal("POST", provider.ReceivedMethod);
        Assert.Equal("/v1/authorizations", provider.ReceivedPath);
        Assert.StartsWith("application/json", provider.ReceivedContentType);
    }

    [Fact]
    public async Task The_request_body_carries_reference_amount_and_normalised_currency()
    {
        var (_, provider) = await Call(200, """{"status":"approved"}""");

        using var doc = JsonDocument.Parse(provider.ReceivedBody!);
        var root = doc.RootElement;
        Assert.Equal(3, root.EnumerateObject().Count());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, _) = await Call(200, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, _) = await Call(200, """{"status":"declined"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        var (outcome, _) = await Call(200, """{"id":"a1","status":"approved","risk":{"score":3}}""");
        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Theory]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"state":"approved"}""")]
    [InlineData("""{"status":null}""")]
    [InlineData("null")]
    public async Task An_unrecognised_answer_is_never_treated_as_approved(string body)
    {
        var (outcome, _) = await Call(200, body);
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_refusal_with_402_is_a_declined_outcome()
    {
        var (outcome, _) = await Call(402, """{"error":"card_refused"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_is_declined_even_if_its_body_claims_approval()
    {
        var (outcome, _) = await Call(402, """{"status":"approved"}""");
        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_failure_statuses_surface_as_errors_not_declines(int status)
    {
        var ex = await Assert.ThrowsAsync<HttpRequestException>(() => Call(status, """{"status":"approved"}"""));
        Assert.Equal((System.Net.HttpStatusCode)status, ex.StatusCode);
    }

    [Fact]
    public async Task A_body_that_is_not_json_surfaces_as_an_error()
    {
        await Assert.ThrowsAsync<JsonException>(() => Call(200, "<html>oops</html>"));
    }
}
